{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/icon-wall.json
    A dense grid of small tiles: an icon and a short label. Axes: columns (3, 4, 6), item (tile: icon above the label, chip: icon beside it), tone, density.
    Props (p): id, title, features, cols, item, tone, density, landmarkLabel. -#}
{%- set v_id = ui_def(p['id'], none) -%}
{%- set v_title = ui_def(p['title'], none) -%}
{%- set v_features = ui_def(p['features'], none) -%}
{%- set v_cols = ui_def(p['cols'], '4') -%}
{%- set v_item = ui_def(p['item'], 'tile') -%}
{%- set v_tone = ui_def(p['tone'], 'default') -%}
{%- set v_density = ui_def(p['density'], 'default') -%}
{%- set v_landmarkLabel = ui_def(p['landmarkLabel'], none) -%}
{%- set v_askedCols = ('2-6' if ui_t(ui_and([ui_eq(v_item, 'chip'), ui_eq(v_cols, '6')])) else ('2' if ui_t(ui_eq(v_cols, '2')) else ('2-3' if ui_t(ui_eq(v_cols, '3')) else ('2-4' if ui_t(ui_eq(v_cols, '4')) else '3-6')))) -%}
{%- set v_wallCols = ui_fit_cols(v_askedCols, ui_len(v_features)) -%}
{%- set c_4 -%}
  {%- set c_3 -%}
    {%- for v_f in ui_l(v_features) %}
      {%- set c_2 -%}
        {{ ui_include('ui/lucide-icon/lucide-icon.html.j2', {'p': {'Name': ui_s(ui_get(v_f, ['icon'])), 'Size': ui_i((24 if ui_t(ui_eq(v_item, 'tile')) else 16))}}) }}
        {%- set c_1 -%}
          {{ ui_text(ui_get(v_f, ['title'])) }}
        {%- endset -%}
        {{ ui_include('ui/text/text.html.j2', {'p': {'Size': 'sm', 'Weight': 'semibold'}, 'children': c_1}) }}
      {%- endset -%}
      {{ ui_include('ui/box/box.html.j2', {'p': {'Class': ui_s(ui_cnv(['flex items-center gap-2', 'rounded bg-card inset-ring inset-ring-border', (ui_cnv(['flex-col justify-center text-center', ('p-4' if ui_t(ui_eq(v_density, 'compact')) else 'p-6')]) if ui_t(ui_eq(v_item, 'tile')) else 'px-4 py-2')])), 'Attrs': ui_attrs(['data-testid', 'item'])}, 'children': c_2}) }}
    {%- endfor %}
  {%- endset -%}
  {{ ui_include('ui/grid/grid.html.j2', {'p': {'Cols': ui_s(v_wallCols), 'Class': 'gap-4', 'Attrs': ui_attrs(['data-testid', 'items'])}, 'children': c_3}) }}
{%- endset -%}
{{ ui_include('blocks/section-frame.html.j2', {'p': {'id': v_id, 'title': v_title, 'tone': v_tone, 'density': v_density, 'landmarkLabel': v_landmarkLabel}, 'children': c_4}) }}
